code.C:
#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    int count = 0;
    for (int i = 0; i < n; i++) if (a[i] > a[(i + 1) % n]) count++;
    printf("%s\n", count <= 1 ? "Yes" : "No");
    return 0;
}

