import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextLong();
            int count = 0;
            for (int i = 0; i < n; i++) if (a[i] > a[(i + 1) % n]) count++;
            System.out.println(count <= 1 ? "Yes" : "No");
        }
    }
}

code.JavaScript:
const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    let count = 0;
    for (let i = 1; i <= n; i++) {
        const curr = BigInt(toks[i]);
        const next = BigInt(toks[i === n ? 1 : i + 1]);
        if (curr > next) count++;
    }
    console.log(count <= 1 ? "Yes" : "No");
}
main();

